mapper.insert:
    	INSERT INTO PRJ_PRJCT_ROLE_BSC_INFO_TBL (
			COMP_SEQ
		  , PRJCT_ROLE_CD
		  , USE_YN
		  , DISP_ORD
		  , PRJCT_ROLE_NM
		  , PRJCT_ROLE_DESC
		  , RGST_DT
		  , RGST_SEQ
		  , RGST_NM
		)
		VALUES (
			#{compSeq, jdbcType=NUMERIC}
		  , 	#{prjctRoleCd, jdbcType=VARCHAR}
		  , 	(
				CASE
					WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{prjctRoleCd, jdbcType=VARCHAR} = '') THEN 'Y'
					ELSE    #{useYn, jdbcType=VARCHAR}
				END	
			)	
		  , 	(
				CASE 
					WHEN (#{dispOrd, jdbcType=NUMERIC} IS NULL OR #{dispOrd, jdbcType=NUMERIC} = 0) THEN (
						SELECT 	MAX(DISP_ORD) + 1
						FROM 	PRJ_PRJCT_ROLE_BSC_INFO_TBL
						WHERE 	1 	= 	1
						AND 		COMP_SEQ = #{compSeq, jdbcType=NUMERIC}
					)
					ELSE #{dispOrd, jdbcType=NUMERIC}
				END	
			)
		  , 	#{prjctRoleNm, jdbcType=VARCHAR}
		  , 	#{prjctRoleDesc, jdbcType=VARCHAR}
		  , CURRENT_TIMESTAMP(3)
		  , #{rgstSeq, jdbcType=NUMERIC}
		  , (
				CASE
					WHEN (#{rgstNm, jdbcType=VARCHAR} IS NULL OR #{rgstNm, jdbcType=VARCHAR} = '') THEN NULL
					ELSE   #{rgstNm, jdbcType=VARCHAR}
				END
		    )
		)

mapper.update:
UPDATE PRJ_PRJCT_ROLE_BSC_INFO_TBL
SET 		USE_YN 	=	(
				CASE 
					WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN USE_YN
					ELSE    #{useYn, jdbcType=VARCHAR}
				END
		    )
		  , DISP_ORD = (
				CASE 
					WHEN (#{dispOrd, jdbcType=NUMERIC} IS NULL OR #{dispOrd, jdbcType=NUMERIC} = 0) THEN DISP_ORD
					ELSE    #{dispOrd, jdbcType=NUMERIC}
				END
		    )
 	 	  , PRJCT_ROLE_NM = (
				CASE 
					WHEN (#{prjctRoleNm, jdbcType=VARCHAR} IS NULL OR #{prjctRoleNm, jdbcType=VARCHAR} = '') THEN PRJCT_ROLE_NM
					ELSE    #{prjctRoleNm, jdbcType=VARCHAR}
				END					
		    )
  		  , PRJCT_ROLE_DESC = (
				CASE 
					WHEN (#{prjctRoleDesc, jdbcType=VARCHAR} IS NULL OR #{prjctRoleDesc, jdbcType=VARCHAR} = '') THEN PRJCT_ROLE_DESC
					ELSE    #{prjctRoleDesc, jdbcType=VARCHAR}
				END					
		    )
  		  , UPDT_DT 	= CURRENT_TIMESTAMP(3)
  		  , UPDT_SEQ 	= #{updtSeq, jdbcType=NUMERIC}
  		  , UPDT_NM 	= (
				CASE
					WHEN (#{updtNm, jdbcType=VARCHAR} IS NULL OR #{updtNm, jdbcType=VARCHAR} = '') THEN UPDT_NM
					ELSE    #{updtNm, jdbcType=VARCHAR}
				END
		    )
WHERE 	1 	= 	1
AND 		COMP_SEQ 		=	#{compSeq, jdbcType=NUMERIC}
AND 		PRJCT_ROLE_CD 	= 	#{prjctRoleCd, jdbcType=VARCHAR}

mapper.delete:
UPDATE  PRJ_PRJCT_ROLE_BSC_INFO_TBL
SET 		USE_YN 		= 	'N' 
		  , DELT_YN 	= 	'Y'
		  , DELT_DT 	= 	CURRENT_TIMESTAMP(3)
		  , DELT_SEQ 	=	(
				CASE
					WHEN ( #{deltSeq, jdbcType=NUMERIC} IS NULL OR  #{deltSeq, jdbcType=NUMERIC} = 0) THEN DELT_SEQ
					ELSE    #{deltSeq, jdbcType=VARCHAR}
				END
		  	)
		  , DELT_NM 	= 	(
				CASE
					WHEN ( #{deltNm, jdbcType=VARCHAR} IS NULL OR  #{deltNm, jdbcType=VARCHAR} = '') THEN DELT_NM
					ELSE    #{deltNm, jdbcType=VARCHAR}
				END
		    )	
WHERE 	1 	= 	1
AND 		DELT_YN 			= 	'N'
AND 		COMP_SEQ 		=	#{compSeq, jdbcType=NUMERIC}
AND 		PRJCT_ROLE_CD 	= 	#{prjctRoleCd, jdbcType=VARCHAR}

mapper.select:
    	SELECT 	(
						CASE
							WHEN (COUNT(PRJCT_ROLE_CD) > 0) THEN true
							ELSE    false 
						END
					) 	AS 	DUP_FLAG
    	FROM 	PRJ_PRJCT_ROLE_BSC_INFO_TBL
    	WHERE 	1 	= 	1
    	AND 		COMP_SEQ 		= 	#{compSeq, jdbcType=NUMERIC}
    	AND 		PRJCT_ROLE_CD 	= 	#{prjctRoleCd, jdbcType=VARCHAR}
